'use strict'

/**
 * cgroup v2 资源控制测试台
 *
 * 运行：sudo node test/test-cgroup.js
 *
 * 需要 root，且会在 cgroup v2 根下临时创建 `cdpcselftest` 控制组（用完删除）。
 * 不满足前提时整体 skip 而不是失败。
 *
 * 覆盖：
 *   create() 一次性带限额创建，各接口文件的实际内容
 *   setMem / setSwap / setCPU / setPids 改限额后**文件里的值真的变了**
 *   memory.max 的强制执行（超限 OOM kill）
 *   cpu.max 的百分比换算
 *   服务自动入组，入组失败时有告警而不是静默无限制
 *   误配保护：memory 小于 1000 字节退回不限制并告警
 */

process.chdir(__dirname)

const fs = require('node:fs')
const os = require('node:os')
const {spawnSync} = require('node:child_process')
const CDPC = require('../index')
const CGroup = require('../cgroup.js')

const CGROOT = '/sys/fs/cgroup'
const GRP = 'cdpcselftest'
const WORKDIR = `${os.tmpdir()}/cdpc-cgroup-test-${process.pid}`

let pass = 0
let fail = 0
let skip = 0
const failed = []

function ok(cond, title, extra = '') {
  if (cond) {
    pass += 1
    console.log(`  \x1b[32mPASS\x1b[0m ${title}`)
  } else {
    fail += 1
    failed.push(title)
    console.log(`  \x1b[31mFAIL\x1b[0m ${title}${extra ? '  <' + extra + '>' : ''}`)
  }
}

function skipAll(why) {
  console.log(`\x1b[33m[SKIP]\x1b[0m ${why}`)
  process.exit(0)
}

const sleep = ms => new Promise(rv => setTimeout(rv, ms))
const rd = f => {
  try { return fs.readFileSync(`${CGROOT}/${GRP}/${f}`, 'utf8').trim() }
  catch (e) { return `<读不到:${e.code}>` }
}

function preflight() {
  if (process.platform !== 'linux') return ' 仅 Linux 有 cgroup'
  if (process.geteuid() !== 0) return '需要 root：cgroup 操作要写 /sys/fs/cgroup'

  try {
    fs.accessSync(`${CGROOT}/cgroup.controllers`)
  } catch (e) {
    return 'cgroup v2 未挂载在 /sys/fs/cgroup（可能是 cgroup v1 系统）'
  }

  let ctl = fs.readFileSync(`${CGROOT}/cgroup.subtree_control`, 'utf8')

  if (ctl.indexOf('memory') < 0) {
    return `根 cgroup 的 subtree_control 未启用 memory（当前：${ctl.trim()}）`
  }

  try { fs.rmdirSync(`${CGROOT}/${GRP}`) } catch (e) {}

  return ''
}

function cleanup() {
  try { fs.rmdirSync(`${CGROOT}/${GRP}`) } catch (e) {}
  spawnSync('rm', ['-rf', WORKDIR], {timeout: 8000})
}

async function main() {
  let why = preflight()

  if (why) skipAll(why)

  fs.mkdirSync(`${WORKDIR}/state`, {recursive: true, mode: 0o755})

  /**
   * 先安静运行一段时间再吃内存：入组检查要在它还活着的时候做。
   * 原来 1.2 秒就分配，OOM kill 发生在检查之前，读到的是 pid=0。
   */
  fs.writeFileSync(`${WORKDIR}/hog.js`, [
    "setInterval(() => {}, 1000)",
    "setTimeout(() => {",
    "  global.b = Buffer.alloc(300 * 1024 * 1024, 1)",
    "  console.log('分配 300MB 成功')",
    "}, 5000)"
  ].join('\n'))

  let cg = new CGroup()

  // ---------------- create()：一次性带限额创建 ----------------
  console.log('\n[1] create()：各接口文件的实际内容')

  await cg.create(GRP, {
    control: ['cpu', 'memory', 'pids'],
    type: 'domain',
    memory: 64 * 1024 * 1024,   // 字节
    cpu: [50000, 100000],       // [quota, period] 微秒 = 50%
    pids: 30
  })

  ok(rd('memory.max') === String(64 * 1024 * 1024),
     'memory.max 按字节原样写入', `实际 ${rd('memory.max')}`)
  ok(rd('cpu.max') === '50000 100000',
     'cpu.max 写入 [quota, period]', `实际 ${rd('cpu.max')}`)
  ok(rd('pids.max') === '30', 'pids.max 写入进程数上限', `实际 ${rd('pids.max')}`)
  ok(rd('memory.swap.max') === '0',
     '限内存时同时把 swap 关掉，否则限额会被 swap 绕过',
     `实际 ${rd('memory.swap.max')}`)

  // ---------------- 各 setter 改限额 ----------------
  console.log('\n[2] setter 改限额：文件里的值必须真的变')

  /**
   * 这一组是回归防线。原实现里 setMem / setSwap 写入的是**改之前的旧值**
   * （先 write(cgrp.memory) 再 cgrp.memory = mem），于是每次调用落后一拍：
   * 第一次等于没改，第二次才把第一次的值写进去。只看返回值 true 是发现不了的。
   */
  let r = await cg.setMem(GRP, 128 * 1024 * 1024)

  ok(r === true && rd('memory.max') === String(128 * 1024 * 1024),
     'setMem 第一次调用就生效（不是落后一拍）',
     `返回 ${r} 实际 ${rd('memory.max')}`)

  r = await cg.setMem(GRP, 256 * 1024 * 1024)

  ok(r === true && rd('memory.max') === String(256 * 1024 * 1024),
     'setMem 连续调用每次都写对', `实际 ${rd('memory.max')}`)
  ok(cg.groupTable[GRP].memory === 256 * 1024 * 1024,
     'groupTable 与文件内容保持一致', `表里 ${cg.groupTable[GRP].memory}`)

  r = await cg.setSwap(GRP, 8 * 1024 * 1024)

  ok(r === true && rd('memory.swap.max') === String(8 * 1024 * 1024),
     'setSwap 同样第一次就生效', `实际 ${rd('memory.swap.max')}`)

  r = await cg.setPids(GRP, 55)

  ok(r === true && rd('pids.max') === '55', 'setPids 生效', `实际 ${rd('pids.max')}`)

  /**
   * 原实现里 setCPU 引用了此作用域并不存在的 `detail`，必然抛 ReferenceError
   * 被 catch 吞掉：cpu.max 其实写成功了，函数却返回 false 且 groupTable 不同步。
   */
  r = await cg.setCPU(GRP, [20000, 100000])

  ok(r === true && rd('cpu.max') === '20000 100000',
     'setCPU 传数组：写入成功且返回值正确', `返回 ${r} 实际 ${rd('cpu.max')}`)

  // 数字形态按百分比换算，原实现没换算就取 cpu[0]，写进去是 "undefined undefined"
  r = await cg.setCPU(GRP, 30)

  ok(r === true && rd('cpu.max') === '30000 100000',
     'setCPU 传数字 30 换算成 30%（30000/100000）', `返回 ${r} 实际 ${rd('cpu.max')}`)

  /**
   * 小百分比是一条真实回归。内核要求 quota >= 1000µs（实测 5.15），而原来的
   * 换算是 `[pct * 100, 10000]` —— 任何小于 10% 的配额 quota 都不足 1000，
   * 内核 EINVAL 拒绝，create() 直接抛错。实测 cpu: 9 / 5 / 1 全部失败，
   * 而文档写的是"数字按百分比"，从没说下限是 10。
   * 改成 `[pct * 1000, 100000]` 后比值不变，1% 正好落在内核下限上。
   */
  for (let [pct, want] of [[9, '9000 100000'], [5, '5000 100000'], [1, '1000 100000']]) {
    r = await cg.setCPU(GRP, pct)
    ok(r === true && rd('cpu.max') === want,
       `setCPU 传 ${pct}（小于 10% 的百分比）能正常落地`,
       `返回 ${r} 实际 ${rd('cpu.max')} 期望 ${want}`)
  }

  r = await cg.setCPU(GRP, 100)

  ok(r === true && rd('cpu.max').indexOf('max') === 0,
     'setCPU 传 100 表示不限制，写入 max', `实际 ${rd('cpu.max')}`)

  ok(await cg.setCPU(GRP, -1) === false, 'setCPU 拒绝负数')
  ok(await cg.setCPU(GRP, [100, 0]) === false, 'setCPU 拒绝 period <= 0')
  ok(await cg.setCPU(GRP, [500, 100000]) === false,
     'setCPU 拒绝 quota < 1000（内核硬下限），不留给内核去 EINVAL')
  ok(await cg.setCPU(GRP, [1000, 2000000]) === false,
     'setCPU 拒绝 period > 1000000（内核硬上限）')

  // create() 的百分比路径同样要覆盖：这才是配置文件里最常见的写法
  for (let pct of [9, 5, 1]) {
    let gname = `${GRP}p${pct}`
    let cgp = new CGroup()
    let threw = ''

    try {
      await cgp.create(gname, {control: ['cpu', 'memory', 'pids'], type: 'domain',
                               cpu: pct, pids: 'max'})
    } catch (e) { threw = e.code || e.message.slice(0, 60) }

    let got = ''
    try { got = fs.readFileSync(`${CGROOT}/${gname}/cpu.max`, 'utf8').trim() } catch (e) {}

    ok(!threw && got === `${pct * 1000} 100000`,
       `create() 传 cpu: ${pct} 不再抛 EINVAL`, `抛错=${threw || '无'} cpu.max=${got}`)

    try { fs.rmdirSync(`${CGROOT}/${gname}`) } catch (e) {}
  }

  // cpu: 0 与 memory / pids / setCPU 保持同一约定：0 = 不限制
  let cgz = new CGroup()
  await cgz.create(`${GRP}zero`, {control: ['cpu', 'memory'], type: 'domain', cpu: 0})

  ok(cgz.groupTable[`${GRP}zero`].cpu === 0,
     'cpu: 0 表示不限制（与 memory / pids / setCPU 的 0 语义一致）',
     JSON.stringify(cgz.groupTable[`${GRP}zero`].cpu))

  try { fs.rmdirSync(`${CGROOT}/${GRP}zero`) } catch (e) {}

  /**
   * 重建时必须把旧限额清掉。
   *
   * "不限制"对 memory / pids 是 'max' —— 一个会被真的写下去的值，所以天然
   * 会覆盖旧值。cpu 的"不限制"是 0，早先这条路**什么都不写**，于是在已存在
   * 的目录上重建时上一次的配额就留着了：先 cpu:50 建组、再改成 cpu:0 重建，
   * cpu.max 仍是 50000 100000 —— 用户以为解除了限制其实没解除。
   * 这是 daemon 重启后重新建组的真实路径。
   */
  const rdIn = (g, f) => {
    try { return fs.readFileSync(`${CGROOT}/${g}/${f}`, 'utf8').trim() } catch (e) { return '' }
  }

  let gr = `${GRP}re`
  let cgReA = new CGroup()
  await cgReA.create(gr, {control: ['cpu', 'memory', 'pids'], type: 'domain',
                        cpu: 50, memory: 64 * 1024 * 1024, pids: 30})

  ok(rdIn(gr, 'cpu.max') === '50000 100000', `前置：重建用例先建出 50% 配额`,
     rdIn(gr, 'cpu.max'))

  let cgReB = new CGroup()
  await cgReB.create(gr, {control: ['cpu', 'memory', 'pids'], type: 'domain',
                        cpu: 0, memory: 'max', pids: 'max'})

  ok(rdIn(gr, 'cpu.max') === 'max 100000',
     '改成 cpu: 0 后重建，旧的 cpu 配额被清除（不是留着不动）', rdIn(gr, 'cpu.max'))
  ok(rdIn(gr, 'memory.max') === 'max', '同样地 memory 也回到不限制', rdIn(gr, 'memory.max'))
  ok(rdIn(gr, 'pids.max') === 'max', '同样地 pids 也回到不限制', rdIn(gr, 'pids.max'))

  try { fs.rmdirSync(`${CGROOT}/${gr}`) } catch (e) {}

  // ---------------- 强制执行 ----------------
  console.log('\n[3] memory.max 的强制执行（内核行为，不是 cdpc 判定）')

  await cg.setMem(GRP, 64 * 1024 * 1024)

  let res = spawnSync('bash', ['-c',
    `echo $$ > ${CGROOT}/${GRP}/cgroup.procs; `
    + `node -e 'global.b = Buffer.alloc(300*1024*1024, 1); console.log("未被杀")'`],
    {encoding: 'utf8', timeout: 60000})

  ok(res.signal === 'SIGKILL' || res.status === 137,
     '限 64MB 时分配 300MB 被内核 OOM kill（收 SIGKILL）',
     `status=${res.status} signal=${res.signal} stdout=${(res.stdout || '').trim()}`)
  ok(/oom_kill (\d+)/.test(rd('memory.events'))
     && parseInt(rd('memory.events').match(/oom_kill (\d+)/)[1], 10) > 0,
     'memory.events 里 oom_kill 计数增加', rd('memory.events').replace(/\n/g, ' '))

  // ---------------- 服务自动入组 ----------------
  console.log('\n[4] 服务自动入组')

  let warns = []
  let cm = new CDPC({
    stateDir: `${WORKDIR}/state`,
    errorHandle: (e, name) => warns.push({name, msg: e && e.message})
  })

  cm.initCgroup()

  ok(!!cm.cgroup, 'root 下 initCgroup 成功挂上 cgroup 模块')

  /**
   * groupTable 是**每个 CGroup 实例各自的内存态**：cgroup 目录在磁盘上存在
   * 不代表这个实例知道它。所以必须用服务所属的那个实例去 create
   * （cdpcd 也是这么做的——启动时在自己的 cm.cgroup 上建好全部预设组）。
   * 先验证「组在磁盘上存在但不在本实例表里」时会明确拒绝而不是假装成功。
   */
  let notMine = await cm.cgroup.addPids(GRP, [process.pid])

  ok(notMine && notMine.ok === false && /未创建/.test(notMine.message || ''),
     '磁盘上已存在但本实例没建过的组，addPids 明确拒绝并说明原因',
     JSON.stringify(notMine))

  await cm.cgroup.create(GRP, {
    control: ['cpu', 'memory', 'pids'],
    type: 'domain',
    memory: 64 * 1024 * 1024,
    cpu: [50000, 100000],
    pids: 30
  })

  ok(rd('memory.max') === String(64 * 1024 * 1024),
     '在已存在的目录上重新 create 不报错且限额正确（daemon 重启后的场景）',
     `实际 ${rd('memory.max')}`)

  cm.add({name: 'hog', file: `${WORKDIR}/hog.js`, restart: 'none', cgroup: GRP,
          options: {stdio: ['ignore', 'ignore', 'ignore']}})

  await sleep(1500)

  let chk = cm.find('hog')
  let pid = chk && chk.child ? chk.child.pid : 0
  let procs = rd('cgroup.procs').split('\n')

  ok(pid > 0 && procs.indexOf(String(pid)) >= 0,
     '配了 cgroup 的服务启动后自动进入该组', `pid=${pid} procs=[${procs.join(',')}]`)
  ok(warns.filter(w => w.name === '--WARN-CGROUP-ATTACH--').length === 0,
     '入组成功时不产生告警')

  // 内核会杀掉它（启动 5 秒后分配 300MB）
  await sleep(6000)

  chk = cm.find('hog')

  ok(cm.stateName[chk.state] === 'EXIT', '超出 cgroup 限额的服务被杀掉',
     `state=${cm.stateName[chk.state]}`)
  ok(chk.signal === 'SIGKILL',
     '终止信号被记录下来 —— 否则详情里只有一个 EXIT，查不出是被 OOM 打死的',
     `code=${chk.code} signal=${chk.signal}`)

  cm.remove('hog')
  await sleep(1000)

  // ---------------- 入组失败必须出声 ----------------
  console.log('\n[5] 入组失败不能静默')

  warns.length = 0

  cm.add({name: 'nogrp', file: `${WORKDIR}/hog.js`, restart: 'none',
          cgroup: 'cdpc-this-group-does-not-exist',
          options: {stdio: ['ignore', 'ignore', 'ignore']}})

  await sleep(2000)

  let attachWarn = warns.find(w => w.name === '--WARN-CGROUP-ATTACH--')

  ok(!!attachWarn,
     '入不了组时抛 --WARN-CGROUP-ATTACH--（否则服务在完全无限制状态下静默运行）')
  ok(attachWarn && /未创建/.test(attachWarn.msg || ''),
     '告警里说明了具体原因，不是「未知原因」', attachWarn ? attachWarn.msg : '')

  cm.remove('nogrp')
  cm.monitorStop()
  await sleep(1000)

  // ---------------- 误配保护 ----------------
  console.log('\n[6] 单位误配保护')

  try { fs.rmdirSync(`${CGROOT}/${GRP}`) } catch (e) {}

  let cg2 = new CGroup()

  // memory: 100 —— 想写 100MB 却按字节传了 100，是最常见的误配
  await cg2.create(GRP, {control: ['memory'], type: 'domain', memory: 100, pids: 'max'})

  ok(rd('memory.max') === 'max',
     'memory 小于 1000 字节被当作误配，退回不限制（不会把服务卡死）',
     `实际 ${rd('memory.max')}`)
  ok(cg2.groupTable[GRP].memory === 'max', 'groupTable 里同步为 max')

  cleanup()

  console.log(`\n${'='.repeat(52)}`)
  console.log(`通过 ${pass}，失败 ${fail}${skip ? `，跳过 ${skip}` : ''}`)

  if (fail > 0) {
    console.log('失败项：')
    for (let f of failed) console.log(`  - ${f}`)
  }

  console.log('='.repeat(52))

  process.exit(fail > 0 ? 1 : 0)
}

main().catch(e => {
  console.error('测试台异常：', e)
  cleanup()
  process.exit(2)
})
